package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import org.cloudburstmc.math.vector.Vector3f; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.v859.serializer.CameraInstructionSerializer_v859; import org.cloudburstmc.protocol.bedrock.data.camera.*; import java.util.*;
public class CameraInstructionSerializer_v924 extends CameraInstructionSerializer_v859 { public static final CameraInstructionSerializer_v924 INSTANCE=new CameraInstructionSerializer_v924();
@Override protected void writeSplineInstruction(ByteBuf b,BedrockCodecHelper h,CameraSplineInstruction s){b.writeFloatLE(s.getTotalTime());b.writeByte(s.getType().ordinal());h.writeArray(b,s.getCurve(),h::writeVector3f);h.writeArray(b,s.getProgressKeyFrames(),(x,f)->{x.writeFloatLE(f.getValue());x.writeFloatLE(f.getTime());x.writeByte(f.getEase().ordinal());});h.writeArray(b,s.getRotationOption(),(x,r)->{h.writeVector3f(x,r.getKeyFrameValues());x.writeFloatLE(r.getKeyFrameTimes());x.writeByte(r.getEase().ordinal());});h.writeString(b,s.getSplineIdentifier());b.writeBoolean(s.isLoadFromJson());}
@Override protected CameraSplineInstruction readSplineInstruction(ByteBuf b,BedrockCodecHelper h){float t=b.readFloatLE();CameraSplineType ty=CameraSplineType.values()[b.readUnsignedByte()];List<Vector3f> c=new ArrayList<>();h.readArray(b,c,h::readVector3f);List<CameraSplineInstruction.SplineProgressOption> p=new ArrayList<>();h.readArray(b,p,x->new CameraSplineInstruction.SplineProgressOption(x.readFloatLE(),x.readFloatLE(),CameraEase.values()[x.readUnsignedByte()]));List<CameraSplineInstruction.SplineRotationOption> r=new ArrayList<>();h.readArray(b,r,x->{Vector3f v=h.readVector3f(x);float kt=x.readFloatLE();CameraEase e=CameraEase.values()[x.readUnsignedByte()];return new CameraSplineInstruction.SplineRotationOption(v,kt,e);});return new CameraSplineInstruction(t,ty,c,p,r,h.readString(b),b.readBoolean());}}
